<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { Download, Eye, ShoppingCart, TrendingUp } from '@lucide/vue';
import { reactive } from 'vue';

import AnalyticsHeader from '@/components/Analytics/AnalyticsHeader.vue';
import DistributionBars from '@/components/Analytics/DistributionBars.vue';
import MetricCard from '@/Components/Shared/MetricCard.vue';
import ShowSection from '@/Components/Show/ShowSection.vue';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
const props=defineProps<{filters:Record<string,string>;report:any}>(); const filters=reactive({...props.filters}); const money=(c:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(c/100); const apply=()=>router.get(`/admin/analytics/assets/${props.report.asset.id}`,filters,{preserveState:true,replace:true});
</script>
<template><Head :title="`${report.asset.title} Performance`"/><div class="analytics-report-page space-y-8 p-6"><AnalyticsHeader :title="report.asset.title" description="Detailed marketplace performance for this asset."><template #actions><Button as-child><Link :href="`/admin/assets/${report.asset.id}`">Manage asset</Link></Button></template></AnalyticsHeader><form class="grid gap-4 rounded-xl border p-4 md:grid-cols-[1fr_1fr_1fr_auto] md:items-end" @submit.prevent="apply"><div class="grid gap-2"><Label>Period</Label><select v-model="filters.period" class="h-10 rounded-md border bg-background px-3"><option value="7_days">Last 7 days</option><option value="30_days">Last 30 days</option><option value="90_days">Last 90 days</option><option value="year_to_date">Year to date</option><option value="custom">Custom</option></select></div><div class="grid gap-2"><Label>Start</Label><Input v-model="filters.start_date" type="date" :disabled="filters.period!=='custom'"/></div><div class="grid gap-2"><Label>End</Label><Input v-model="filters.end_date" type="date" :disabled="filters.period!=='custom'"/></div><Button>Apply</Button></form><section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="Views" :value="report.performance.views.toLocaleString()"><template #icon><Eye class="h-5 w-5"/></template></MetricCard><MetricCard label="Units sold" :value="report.performance.units_sold.toLocaleString()"><template #icon><ShoppingCart class="h-5 w-5"/></template></MetricCard><MetricCard label="Revenue" :value="money(report.performance.revenue_cents)" emphasized><template #icon><TrendingUp class="h-5 w-5"/></template></MetricCard><MetricCard label="Downloads" :value="report.performance.downloads.toLocaleString()"><template #icon><Download class="h-5 w-5"/></template></MetricCard></section><section class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><MetricCard label="View to cart" :value="`${report.performance.view_to_cart_percent}%`"/><MetricCard label="View to purchase" :value="`${report.performance.view_to_purchase_percent}%`"/><MetricCard label="Cart to purchase" :value="`${report.performance.cart_to_purchase_percent}%`"/><MetricCard label="Revenue per view" :value="money(report.performance.revenue_per_view_cents)"/></section><div class="grid gap-6 xl:grid-cols-2"><ShowSection title="Revenue by license"><DistributionBars :items="report.license_mix"/></ShowSection><ShowSection title="Offerings"><div class="space-y-3"><div v-for="offering in report.offerings" :key="offering.id" class="rounded-lg border p-3"><div class="font-medium">{{ offering.name }}</div><div class="text-sm text-muted-foreground">{{ offering.license }} · {{ offering.image_units }} image units · {{ offering.video_units }} video units</div></div><p v-if="!report.offerings.length" class="text-sm text-muted-foreground">No offerings configured.</p></div></ShowSection></div><ShowSection title="Daily performance"><div class="overflow-x-auto rounded-lg border"><table class="w-full text-sm"><thead class="bg-muted/50"><tr><th class="p-3 text-left">Date</th><th class="p-3 text-right">Views</th><th class="p-3 text-right">Favorites</th><th class="p-3 text-right">Cart</th><th class="p-3 text-right">Units</th><th class="p-3 text-right">Revenue</th></tr></thead><tbody class="divide-y"><tr v-for="day in report.timeline" :key="day.date"><td class="p-3">{{ day.label }}</td><td class="p-3 text-right">{{ day.views }}</td><td class="p-3 text-right">{{ day.favorites }}</td><td class="p-3 text-right">{{ day.cart_additions }}</td><td class="p-3 text-right">{{ day.units }}</td><td class="p-3 text-right">{{ money(day.revenue_cents) }}</td></tr></tbody></table></div></ShowSection></div></template>
